void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
	vec2 uv = (fragCoord.xy / iResolution.xy) - .5;
	float t = iTime * .1 + ((.25 + .05 * sin(iTime * .1))/(length(uv.xy) + .07)) * 2.2;
	float si = sin(t);
	float co = cos(t);
	mat2 ma = mat2(co, si, -si, co);

vec4 o=fragColor;
vec2 u =fragCoord;
 vec3 c = iResolution;


    float i, t2 = .01*iTime;
    u = .4*(u+u-c.xy)/c.y + t2;   
    for (o *= i; ++i<14.; o = sqrt(o*o+.7)*.99) 
        u *= -.1*mat2(5, 11, -11, 5), // 1.2*rot(2)
        u += cos(u.yx/.1+ .4*i*o.xz)*.003*i + t2/i,
        c = cos(3.*t2+vec3(cos(u*1e2),1)/8.+o.x*i/9.+u.x*.4*i+sin(u.y*i)),
        o.rgb += c*pow(c*c, vec3(0,1.5,4))/pow(i,i/43.),
        u += sin(u.yx)*o.z*.03;
    o = 1.-exp(-.018*o*o*o.r);


	float v1, v2, v3;
	v1 = v2 = v3 = 0.0;
	vec2 u2 =fragCoord;
    vec2 v = iResolution.xy;
         u2 = .2*(u2+u2-v)/v.y;    
         vec4 o2=fragColor;
    vec4 z = o2 = vec4(1,2,3,0);
     u2*=3.;
    for (float a = .5, t3 = iTime, i; 
         ++i < 19.; 
         o2 += (1. + cos(z+t3)) 
            / length((1.+i*dot(v,v)) 
                   * sin(1.5*u2/(.5-dot(u,u)) - 9.*u2.yx + t3))
         )  
        v = cos(++t3 - 7.*u2*pow(a += .03, i)) - 5.*u2,                 
        u += tanh(40. * dot(u2 *= mat2(cos(i + .02*t3 - vec4(0,11,33,0)))
                           ,u2)
                      * cos(1e2*u.yx + t3)) / 2e2
           + .2 * a * u2
           + cos(4./exp(dot(o2,o2)/1e2) + t3) / 3e2;

     o2 = 25.6 / (min(o2, 13.) + 164. / o2) 
       - dot(u2, u2) / 250.;
	float s = 0.0;
	for (int i = 0; i < 90; i++)
	{
		vec3 p = s * vec3(uv, 0.0)*o2.xyz;

		p += vec3(.22, .3, s - 1.5 - sin(iTime * .13) * .1);
		for (int i = 0; i < 8; i++)	p = abs(p) / dot(p,p) - 0.659;
		v1 += dot(p,p) * .0015 * (1.8 + sin(length(uv.xy * 13.0) + .5  - iTime * .2));
		v2 += dot(p,p) * .0013 * (1.5 + sin(length(uv.xy * 14.5) + 1.2 - iTime * .3));
		v3 += length(p.xy*10.) * .0003;
		s  += .035;
	}

	float len = length(uv);
	v1 *= smoothstep(.7, .0, len);
	v2 *= smoothstep(.5, .0, len);
	v3 *= smoothstep(.9, .0, len);

	vec3 col = vec3( v3 * (1.5 + sin(iTime * .2) * .4),
					(v1 + v3) * .3,
					 v2) + smoothstep(0.2, .0, len) * .85 + smoothstep(.0, .6, v3) * .3;

	fragColor=vec4(min(pow(abs(col)+o2.xyz*o.xyz, vec3(1.2)), 1.0), 1.0);

}
